# 本次先採用前 18 篇國中優先候選；其餘候選保留在腳本中供後續擴充。
entries = entries[:18]

# 使用 18 個占位編號；若新增項目不足，立即失敗而不破壞資料庫。
if len(entries) != 18:
    raise SystemExit(f'需要 18 篇，實際 {len(entries)} 篇')

data = json.loads(DB.read_text(encoding='utf-8'))
placeholders = [item for item in data if 83 <= item.get('no', 0) <= 100]
if len(placeholders) != 18:
    raise SystemExit(f'預期 18 個占位項目，實際 {len(placeholders)} 個')
existing_titles = {item['title'] for item in data if item.get('no', 0) < 83}
new_titles = [item['title'] for item in entries]
if existing_titles.intersection(new_titles):
    raise SystemExit(f'新篇與既有篇目重複：{existing_titles.intersection(new_titles)}')

for slot, entry in zip(placeholders, entries):
    slot.update({
        'title': entry['title'],
        'author': entry['author'],
        'dynasty': entry['dynasty'],
        'genre': entry['genre'],
        'category': entry['category'],
        'core': entry['core'],
        'source': entry['source'],
        'contentStatus': '來源補齊－待教師校對',
        'translationStatus': '人工重寫語譯',
        'sections': entry['sections'],
    })

DB.write_text(json.dumps(data, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(f'已替換 {len(entries)} 篇，資料庫仍為 {len(data)} 篇。')
print('替換篇目：' + '、'.join(new_titles))
